/// Greatest common divisor of two strictly positive integers.
///
/// Uses Euclid's algorithm with remainder, which is equivalent to repeatedly
/// applying the subtraction rule but runs in O(log min(m, n)) time.
pub fn gcd_i(m: u64, n: u64) -> u64 {
    assert!(m > 0 && n > 0, "inputs must be strictly positive");

    let mut a = m;
    let mut b = n;

    // Invariant: gcd(a, b) == gcd(m, n) and a > 0, b >= 0.
    while b != 0 {
        let r = a % b; // safe because b != 0
        a = b;
        b = r;
    }

    // When b == 0, a is the gcd.
    a
}

